#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/recursive_semantic_v14_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/recursive_improvement_controller.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > "$PREFIX/tmp/companyos_recursive_semantic_v14_patch.py"
python "$PREFIX/tmp/companyos_recursive_semantic_v14_patch.py"
rm -f "$PREFIX/tmp/companyos_recursive_semantic_v14_patch.py"

echo "" | base64 -d > tests/test_recursive_semantic_integration_v14.py
echo "" | base64 -d > scripts/companyos_recursive_report
chmod +x scripts/companyos_recursive_report

echo "[1/8] Compile"
python -m py_compile companyos/runtime/recursive_improvement_controller.py tests/test_recursive_semantic_integration_v14.py

echo "[2/8] Integration tests"
python -m unittest tests.test_recursive_semantic_integration_v14 -v

echo "[3/8] Current semantic state"
scripts/companyos_semanticctl status || true

echo "[4/8] Run one bounded recursive semantic cycle"
scripts/companyos_recursive_ctl once | tee .companyos_runtime/recursive_improvement_v14_first_cycle.json || true

echo "[5/8] Show queue + inventory"
scripts/companyos_compoundctl requests || true
scripts/companyos_expandctl inventory || true

echo "[6/8] Refresh feedback"
scripts/companyos_feedbackctl once || true

echo "[7/8] Commit/push"
git add companyos/runtime/recursive_improvement_controller.py tests/test_recursive_semantic_integration_v14.py scripts/companyos_recursive_report
git diff --cached --quiet || git commit -m "Feed semantic capability outputs into recursive improvement loop"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[8/8] Restart + verify"
scripts/companyosctl restart || true
sleep 8

scripts/companyos_recursive_report || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_RECURSIVE_SEMANTIC_EXPANSION_V14=PASS"
